import {feedMesh,feedCylinder,feedTransform,feedSocket,feedCurvedFoot} from './feed-solids.js';
export const FEED={engagement:18,minEngagement:16,maxEngagement:19,socketLength:22,endClearance:4,puckRadius:26};
const FEED_TAU=2*Math.PI;
const fz=(r,p)=>r*r/(4*p.diameter*p.fd);
const fhole=(r,a=0,w=3.4)=>({r0:r-w/2,r1:r+w/2,a0:a-w/(2*r),a1:a+w/(2*r),r,a,w,shape:'round'});
export function feedDatum(p){const r=p.diameter/2-11;return{r,front:fz(r,p)+3.08,rear:fz(r,p)-p.thickness-5,slope:r/(2*p.diameter*p.fd),holes:[fhole(r,-10/r),fhole(r,10/r)]};}
export function feedFits(p,n,rows){if(!p.feedMode)return true;if(n%p.feedLegs)return false;const d=feedDatum(p),r0=45+(rows-1)*(p.diameter/2-45)/rows;return d.r-15>Math.max(78,r0+8)&&d.r*Math.sin(Math.PI/n)>27;}
export function addFeedPad(spec,p){
 const d=feedDatum(p),oldBack=spec.backFn,oldLevels=[...spec.levels];
 const weight=(x,y)=>{const q=Math.max(Math.abs(Math.hypot(x,y)-d.r)-10,Math.abs(y)-14,0),t=Math.min(1,q/4);return 1-t*t*(3-2*t);};
 const delta=(x,y)=>Math.max(0,oldBack(x,y)-(d.rear+d.slope*(x-d.r)))*weight(x,y);
 spec.backFn=(x,y)=>oldBack(x,y)-delta(x,y);spec.levels=oldLevels.map((fn,i)=>i===oldLevels.length-1?fn:(x,y)=>fn(x,y)-delta(x,y));
 spec.feedHoles=d.holes;spec.feedDatum=d;spec.layers=spec.layers.map(layer=>({...layer,holes:[...(layer.holes||[]),...d.holes]}));spec.gridBoxes.push(...d.holes,...[10,14].map(t=>({r0:d.r-t,r1:d.r+t,a0:-t/d.r,a1:t/d.r})));spec.extraR=[...(spec.extraR||[]),d.r-10,d.r,d.r+10];return spec;
}
function hyperbola(p,ratio){
 const f=p.diameter*p.fd,g=p.backFocus,zv=f*ratio,zc=(f+g)/2,c=(f-g)/2,a=zv-zc,b2=c*c-a*a;
 if(!(g<0&&a>0&&a<c&&b2>0))throw Error('Secondary vertex must lie between the two-focus midpoint and primary focus.');
 const surface=r=>zc+a*Math.sqrt(1+r*r/b2),R=p.diameter/2,depth=fz(R,p);let lo=0,hi=R;for(let i=0;i<70;i++){const r=(lo+hi)/2;if(surface(r)<f+(depth-f)*r/R)lo=r;else hi=r;}
 const intercept=(lo+hi)/2,radius=intercept*1.04,edgeZ=surface(radius),backZ=zv+10,returnRadius=intercept*(fz(60,p)-g)/(surface(intercept)-g);
 return{primaryFocus:f,backFocus:g,vertex:zv,center:zc,c,a,b2,interceptRadius:intercept,radius,edgeZ,backZ,returnRadius,surface,ratio};
}
export function cassegrainGeometry(p){
 let s,target=null;if(p.autoSecondary&&p.frequencyGHz>0){target=Math.max(56,p.secondaryWaves*299.792458/p.frequencyGHz);if(target>p.diameter*.25)throw Error('Requested wavelength-sized secondary exceeds 25% of dish diameter. Use prime focus, a larger dish, or manual secondary geometry for an explicitly experimental layout.');let lo=Math.max(.5001,(p.diameter*p.fd+p.backFocus)/(2*p.diameter*p.fd)+.001),hi=.98;for(let i=0;i<60;i++){const mid=(lo+hi)/2;if(hyperbola(p,mid).radius*2>target)lo=mid;else hi=mid;}s=hyperbola(p,(lo+hi)/2);}else s=hyperbola(p,p.secondaryPosition);
 if(s.radius<28-1e-7||s.radius>p.diameter*.125+1e-7)throw Error('Secondary must be at least 56 mm across and no more than 25% of the dish diameter for this compact support.');
 if(s.returnRadius>13.5)throw Error('Returned ray bundle does not clear the 30 mm hub with 1.5 mm radial margin. Move the rear focus toward the vertex.');
 return{...s,targetDiameter:target};
}
export function feedGeometry(p,layout){
 if(!p.feedMode)return null;const d=feedDatum(p),lambda=p.frequencyGHz>0?299.792458/p.frequencyGHz:null,secondary=p.feedMode===2?cassegrainGeometry(p):null;
 const offset=p.feedMode!==1?0:p.phaseUnits===1?(lambda===null?NaN:p.phaseOffset*lambda):p.phaseOffset;if(!Number.isFinite(offset))throw Error('Enter a frequency for a phase-center offset specified in wavelengths.');
 const lowerZ=d.front+4,topRadius=18;
 const requiredFace=secondary?lowerZ+(secondary.edgeZ+10-lowerZ)*(d.r-topRadius)/(d.r-secondary.radius-7)-8:0;
 const stemHeight=secondary?Math.max(10,5*Math.ceil((requiredFace-secondary.backZ)/5)):0;
 const carrierFace=secondary?secondary.backZ+stemHeight:p.diameter*p.fd-offset,upperZ=carrierFace+8;
 const distance=Math.hypot(d.r-topRadius,upperZ-lowerZ),cut=distance-2*FEED.endClearance;
 if(upperZ-lowerZ<15||distance<60||cut>600)throw Error('Rod geometry is outside the compact fitting envelope: require at least 15 mm rise, 60 mm span and at most 600 mm cut.');
 // Conservative single-rod cantilever screening, NOT a full truss/load model.
 // E=69 GPa; full entered payload acts transversely on one rod; 1 mm or lambda/50 target.
 const targetDeflection=Math.min(1,lambda===null?1:lambda/50),load=p.feedPayload/1000*9.80665,L=distance-44;
 const deflection=diameter=>load*L**3/(3*69000*(Math.PI*diameter**4/64));
 const diameter=p.rodDiameter||[4,5,6,6.35,8].find(d=>deflection(d)<=targetDeflection);
 if(!diameter)throw Error('No 4–8 mm solid aluminum rod meets the screening deflection budget. Reduce payload/span or engineer a tubular support.');
 const phase=p.staggerRings?((layout.rows-1)%2)*Math.PI/layout.n:0,legs=Array.from({length:p.feedLegs},(_,i)=>{const angle=phase+i*FEED_TAU/p.feedLegs;return{number:i+1,angle,lower:[d.r*Math.cos(angle),d.r*Math.sin(angle),lowerZ],upper:[topRadius*Math.cos(angle),topRadius*Math.sin(angle),upperZ],pivotDistance:distance,cutLength:cut};});
 if(secondary){const rr=secondary.radius+diameter/2+1,z=lowerZ+(upperZ-lowerZ)*(d.r-rr)/(d.r-topRadius);if(z<secondary.edgeZ+3+diameter/2+1)throw Error('Rod path crowds the secondary edge. Change secondary position, rear focus or dish geometry.');}
 const warnings=['Prototype: no wind, payload or RF performance rating. Small radial screws require physical slip and warm-creep tests.'];
 if(p.feedLegs===4)warnings.push('Fit the fourth rod last without preload; never use it to pull a warped petal into alignment.');
 if(!lambda)warnings.push('Frequency unspecified: wavelength-dependent dimensions and RF tolerances are unavailable.');
 if(p.feedMode===1&&offset===0)warnings.push('Zero phase-center offset is a placeholder; specify the actual feed datum.');
 if(deflection(diameter)>targetDeflection)warnings.push('Selected rod exceeds the conservative deflection screening budget; use larger stock or reduce payload.');
 if(secondary){warnings.push('Hyperbolic ray geometry is not electromagnetic validation. A frequency-specific rear feed remains required.');if(lambda&&2*secondary.radius/lambda<5)warnings.push('Secondary is below five wavelengths: diffraction requires full-wave or hybrid electromagnetic analysis.');}
 return{mode:p.feedMode===1?'prime-focus':'cassegrain',legs,datum:d,carrierFace,upperZ,lowerZ,cutLength:cut,pivotDistance:distance,rodAngle:Math.atan2(upperZ-lowerZ,d.r-topRadius)*180/Math.PI,phase,secondary,stemHeight,offset,rodDiameter:diameter,lambda,targetDeflection,screenDeflection:deflection(diameter),surfaceRmsBudget:lambda?lambda/40:null,warnings};
}
const transform=(mesh,fn)=>({v:mesh.v.map(fn),f:mesh.f});
const flip=mesh=>transform(mesh,([x,y,z])=>[x,-y,-z]);
function socketFrame(A,B,azimuth=0){const dx=B[0]-A[0],dz=B[2]-A[2],L=Math.hypot(dx,dz),u=dx/L,w=dz/L;return([x,y,z])=>{const X=A[0]+w*x+u*z,Y=A[1]+y;return[Math.cos(azimuth)*X-Math.sin(azimuth)*Y,Math.sin(azimuth)*X+Math.cos(azimuth)*Y,A[2]-u*x+w*z];};}
export function appendFeedParts(m,api){
 if(!m.p.feedMode)return;const{patch,printMesh,bounds}=api,p=m.p,g=feedGeometry(p,m.layout),d=g.datum;m.feed=g;
 const add=(id,name,mesh,qty,angles=[0],printing=null)=>{const pm=printing||printMesh(mesh),dim=bounds(pm).size;if(dim[0]>p.bedX-2*p.margin||dim[1]>p.bedY-2*p.margin||dim[2]>p.bedZ-2)throw Error(name+' does not fit the print volume.');const part={id,name,mesh,print:pm,output:pm,supportMeshes:[],dim,qty,kind:'feed',row:-1,angle:0,bedRotation:0,spec:{holes:[]}};m.parts.push(part);for(const a of angles)m.instances.push({part,a});return part;};
 const angles=g.legs.map(x=>x.angle),box={r0:d.r-10,r1:d.r+10,a0:-14/d.r,a1:14/d.r,holes:d.holes};
 const low=[d.r,0,g.lowerZ],high=[18,0,g.upperZ],socket=feedSocket(g.rodDiameter,p.rodClearance),frame=socketFrame(low,high);
 let shoe=feedCurvedFoot(d.r,10,d.front+3,p.diameter*p.fd).union(feedCylinder([d.r,0,fz(d.r+5,p)+.15],[d.r,0,d.front+8],5,20)).union(feedTransform(socket.body,frame));for(const c of socket.cuts)shoe=shoe.subtract(feedTransform(c,frame));
 // Feet screws pass through the socket union too. Use underside counters-free M3 bolts.
 for(const h of d.holes)shoe=shoe.subtract(feedCylinder([h.r*Math.cos(h.a),h.r*Math.sin(h.a),d.rear-5],[h.r*Math.cos(h.a),h.r*Math.sin(h.a),d.front+22],1.7,24));
 const shoeMesh=feedMesh(shoe);add('feed-rim-shoe','Feed · compact bolted rim shoe',shoeMesh,p.feedLegs,angles,printMesh(transform(shoeMesh,([x,y,z])=>[x,z,-y])));
 const backer=patch({...box,topFn:(x)=>d.rear+d.slope*(x-d.r)-.08,backFn:(x)=>d.rear+d.slope*(x-d.r)-3.08},p);add('feed-backer','Feed · slim rim backer',backer,p.feedLegs,angles,printMesh(backer,Math.atan(d.slope)));
 let puck=feedCylinder([0,0,g.carrierFace],[0,0,g.carrierFace+16],FEED.puckRadius,32),cuts=[];
 if(g.secondary)puck=puck.union(feedCylinder([0,0,g.secondary.backZ],[0,0,g.carrierFace+1],9,32));
 for(const a of angles){const fn=socketFrame(high,low,a);puck=puck.union(feedTransform(socket.body,fn));cuts.push(...socket.cuts.map(c=>feedTransform(c,fn)));}
 cuts.push(feedCylinder([0,0,g.carrierFace-20],[0,0,g.carrierFace+20],g.secondary?2.3:6,32));
 for(let i=0;i<p.feedLegs;i++){const a=g.phase+(i+.5)*FEED_TAU/p.feedLegs,x=12*Math.cos(a),y=12*Math.sin(a);cuts.push(feedCylinder([x,y,g.carrierFace-1],[x,y,g.carrierFace+17],1.7,20));}
 for(const c of cuts)puck=puck.subtract(c);const pm=feedMesh(puck);add('feed-puck','Feed · compact round puck',pm,1,[0],printMesh(flip(pm)));
 if(g.secondary){const s=g.secondary,back=(x,y)=>{const r=Math.hypot(x,y),t=Math.min(1,Math.max(0,(r-10)/5));return Math.max(s.surface(r)+3,s.backZ*(1-t)+(s.surface(r)+3)*t);};const h={r0:0,r1:2.8,a0:0,a1:FEED_TAU},front=(x,y)=>s.surface(Math.hypot(x,y)),mesh=patch({r0:0,r1:s.radius,a0:0,a1:FEED_TAU,levels:[front,(x,y)=>front(x,y)+.3*(back(x,y)-front(x,y)),back],layers:[{},{holes:[h]}],gridBoxes:[h],extraR:[10,15]},p);add('secondary-reflector','Secondary · 3 mm shell / center boss',mesh,1,[0],printMesh(flip(mesh)));}
}
export function feedManifest(m){if(!m.feed)return{enabled:false};const g=m.feed,s=g.secondary;return{enabled:true,revision:2,mode:g.mode,legs:m.p.feedLegs,rod_diameter_mm:g.rodDiameter,stock:'smooth solid aluminum rod (screen assumes E = 69 GPa)',cut_length_mm:g.cutLength,socket_end_span_mm:g.pivotDistance,nominal_engagement_each_end_mm:18,engagement_range_mm:[16,19],carrier_lower_face_z_mm:g.carrierFace,phase_center_offset_mm:g.offset,frequency_GHz:m.p.frequencyGHz||null,wavelength_mm:g.lambda,surface_rms_screen_mm:g.surfaceRmsBudget,rod_deflection_screen_mm:g.screenDeflection,rod_deflection_budget_mm:g.targetDeflection,payload_input_g:m.p.feedPayload,puck_body_diameter_mm:52,adapter_bolt_circle_mm:24,adapter_bolts:`${m.p.feedLegs} × M3 midway between rods; feed-specific adapter required`,legs_geometry:g.legs,secondary:s?{primary_focus_z:s.primaryFocus,rear_focus_z:s.backFocus,vertex_z:s.vertex,vertex_ratio:s.ratio,diameter_mm:2*s.radius,target_diameter_mm:s.targetDiameter,front_surface:'z = center + a * sqrt(1 + r^2 / b^2)',center:s.center,a:s.a,b:Math.sqrt(s.b2),back_boss_z:s.backZ,return_bundle_radius_mm:s.returnRadius}:null,hardware:feedHardware(m),warnings:g.warnings};}
export function rodCSV(m){if(!m.feed)return'';return 'leg,stock,diameter_mm,socket_end_span_mm,engagement_each_mm,cut_length_mm,cut_length_inches,azimuth_degrees,rod_elevation_degrees,lower_end_z_mm,upper_end_z_mm\n'+m.feed.legs.map(l=>[l.number,'smooth solid aluminum',m.feed.rodDiameter,l.pivotDistance.toFixed(3),18,l.cutLength.toFixed(3),(l.cutLength/25.4).toFixed(4),(l.angle*180/Math.PI).toFixed(3),m.feed.rodAngle.toFixed(3),l.lower[2].toFixed(3),l.upper[2].toFixed(3)].join(',')).join('\n')+'\n';}
export function feedHardware(m){if(!m.feed)return[];const n=m.p.feedLegs,d=m.feed.datum,grip=d.front-d.rear+3.18,length=[16,20,25,30,35,40,45,50].find(x=>x>=grip+5);if(!length)throw Error('Rim-foot screw stack exceeds M3×50.');return[
 {item:'rim-foot screw',spec:`M3 × ${length}`,quantity:2*n,grip_mm:grip,note:'Install from rear; two 0.5 mm washers and M3 nut. Check access/stack before tightening.'},
 {item:'rod-retention screw',spec:'M3 × 10',quantity:2*n,note:'Real M3 nut in side pocket; rounded screw tip against solid rod. Slip-test; do not crush tubing.'},
 {item:'M3 nut',spec:'5.5 mm AF / 2.4 mm height',quantity:4*n,note:'Rim and socket retention; pocket allows 5.8 mm AF'},
 {item:'M3 washer',spec:'0.5 mm thick',quantity:4*n,note:'Both faces of each rim bolt'},
 ...(m.feed.secondary?[{item:'secondary screw',spec:`M4 × ${m.feed.stemHeight+25}`,quantity:1,note:`${m.feed.stemHeight+16} mm puck/stem stack + 4 mm metal washer/spacer stack; nominal 5 mm entry. Verify actual insert/tip clearance.`},{item:'M4 washer',spec:'1 mm thick',quantity:4,note:'4 mm total metal spacer/washer stack under secondary screw'},{item:'secondary insert',spec:'short M4 / maximum 6 mm / compatible with 5.6 mm pilot',quantity:1,note:'7 mm blind pocket; insert 0.5 mm below boss face'}]:[])];}
export function feedHardwareCSV(m){const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';return 'item,specification,quantity,grip_mm,note\n'+feedHardware(m).map(x=>[x.item,x.spec,x.quantity,x.grip_mm?.toFixed(3),x.note].map(quote).join(',')).join('\n')+'\n';}
export function feedGuide(m){if(!m.feed)return'';const g=m.feed;return `# PETAL compact rod support · ${g.mode}\n\nAccessory revision 2. Regenerate the mount petals, rim shoes, backers and puck together. These fittings replace revision 1 hinges and are not interchangeable. Seam/hub interface remains revision 9. Changing rod count can change dish segmentation; regenerate the complete matching kit if it does.\n\n## Small parts, long metal rods\n\n${m.p.feedLegs} × Ø${g.rodDiameter} mm smooth SOLID aluminum rods; nominal cut ${g.cutLength.toFixed(2)} mm each. No threaded rod. Tubing needs a separate crush-resistant clamp and stiffness calculation. The selected outer petals have compact paired M3 mounting holes near the rim; shoes bolt on, with a small rear backer. These holes remain through holes in all seam-fastener modes. There is no printed snap latch to carry sustained load. Use the supplied mount petals, not holes drilled blindly into an existing rib.\n\nSocket axes are generated at ${g.rodAngle.toFixed(2)}° above the dish plane. Socket end-to-end span ${g.pivotDistance.toFixed(2)} mm; each mouth is 22 mm from its blind end, with 18 mm nominal engagement. Cut = span − 2×(22−18). Deburr and mark 18 mm insertion; keep 16–19 mm engagement (at least 1 mm clearance above the bore floor at maximum insertion). Trial-fit long stock and trim; do not force rods against blind ends. RODS.csv contains actual positions, angle, diameter and cuts.\n\n## Assembly and printing\n\nPrint one shoe and the puck first. Nominal diametral rod clearance is ${m.p.rodClearance.toFixed(2)} mm; adjust it after a fit coupon/test socket, not by forcing the rod. Shoes export on their side; puck exports top-face down. Inspect socket bores, nut cavities and screw channels in the slicer and support horizontal roofs as required. Ream gently to a sliding fit. Backers print flat. PETG is a practical indoor fit-test material; ASA is preferable for outdoor UV exposure with an enclosed printer. Neither removes polymer creep: qualify at actual temperature/load. Use at least four perimeters and locally solid socket/boss walls, not an infill percentage as a strength guarantee.\n\nInstall rear backer → mount petal → rim shoe. Use M3 hardware in FEED-HARDWARE.csv, separate from dish bolts. The two shoe bolts are alongside the rod socket; tighten before fitting rods. Fit real M3 nuts into the side-loading hex pockets; a small retaining dab of adhesive may hold the nut during assembly, but keep the threads and rod bore clean. M3×10 radial screws retain smooth solid rods. Rounded tips reduce gouging; do not substitute hollow tubing without a revised clamp. Mark rods to reveal slip. No printed threads.\n\nSupport the puck with an independent height/centering jig, slide all rods freely into place and tighten progressively. For four rods, fit the fourth last at zero preload. Never use screws to pull a distorted petal or puck into position. Measure center/height/tilt before and after tightening, after changing elevation, and after warm soaking. Strain-relieve the feed cable along a rod. The compact puck has ${m.p.feedLegs} M3 adapter bores on 24 mm BCD, halfway between rods, and ${g.secondary?'a central M4 clearance hole':'a 12 mm cable opening'}. This is a PETAL interface, not a universal RF feed flange. Feed-specific adapter and fasteners are not included.\n\n## Frequency and optical meaning\n\n${g.lambda?`Frequency ${m.p.frequencyGHz} GHz gives wavelength ${g.lambda.toFixed(3)} mm. Surface RMS screening target λ/40 = ${g.surfaceRmsBudget.toFixed(3)} mm, including printing, assembly and metallization errors. This is a design budget, not measured accuracy. The rod screening budget is min(1 mm, λ/50) = ${g.targetDeflection.toFixed(3)} mm.`:'Frequency is unknown; enter it to enable wavelength-based dimensions and accuracy guidance.'}\n\nFrequency alone does not move the focus of a fixed parabola. Prime focus remains f = D × f/D = ${m.focal.toFixed(3)} mm. A phase-center offset can be entered in mm or wavelengths ONLY when supported by the chosen feed design; scaling a generic unknown feed is not valid. The puck lower-face datum is z=${g.carrierFace.toFixed(3)} mm; phase-center offset is ${g.offset.toFixed(3)} mm along +z.\n\n${g.secondary?`The secondary is a convex hyperboloid toward the main dish: vertex z=${g.secondary.vertex.toFixed(3)} mm, diameter ${(2*g.secondary.radius).toFixed(3)} mm, rear focus z=${g.secondary.backFocus.toFixed(3)} mm. Automatic mode targets the entered secondary wavelength count (minimum 56 mm mechanical diameter), solves its position and then recalculates rod lengths and angles. Above 25% dish diameter it rejects the combination; choose prime focus or a larger dish. These are engineering screening limits, not optimized RF dimensions. The 3 mm reflective shell has a central 10 mm boss with one blind Ø5.6×7 mm insert pocket. Install a short M4 insert at least 0.5 mm recessed, maximum 6 mm long; use M4×${g.stemHeight+25} with a 4 mm metal washer/spacer stack through the ${g.stemHeight+16} mm puck/stem stack. Verify actual engagement and leave the reflective face intact. Secondary prints with its boss down; support the surrounding back shell in the slicer. The rear RF feed, phase center, polarization and illumination must be designed separately.`:'Place the actual feed PHASE CENTER at the focus, not automatically its mouth or flange. A zero offset remains unverified. The feed points toward the main dish.'}\n\nAuto rod sizing screens 4, 5, 6, 6.35 and 8 mm SOLID aluminum using E=69 GPa and a deliberately conservative single cantilever with the entire entered ${m.p.feedPayload} g payload applied transversely over the exposed span: δ=FL³/(3EI). Selected-rod result ${g.screenDeflection.toFixed(3)} mm. Include feed/secondary, puck, adapter and cable loads in the payload input; wind, joint compliance, resonance and creep are excluded. This is not an allowable-load calculation or an RF guarantee. Manual diameter overrides retain an over-budget warning.\n\n${g.warnings.map(w=>'- '+w).join('\n')}\n\nCoat the dish-facing secondary surface with continuous bonded aluminum/copper foil or a verified conductive coating; ordinary metallic paint is not sufficient evidence of RF conductivity. Keep datums, bores and the boss back clean. Surface seams/wrinkles count toward the RF error budget. Test one assembled leg for slip and creep, then the complete assembly at several elevations before committing to a full outdoor installation.\n`;}
